{"command":"python3 -c "
import csv

# Check that all stops from input are in output with correct column mapping
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    input_stops = {row['stop_id']: row for row in reader}

with open('outputs/t06_stop_service_intensity.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    output_stops = {row['stop_id']: row for row in reader}

# Check all input stops are in output
for stop_id in input_stops:
    if stop_id not in output_stops:
        print(f'Missing stop_id in output: {stop_id}')

# Check stop_name, stop_lat, stop_lon are copied correctly
for stop_id in input_stops:
    if stop_id in output_stops:
        inp = input_stops[stop_id]
        out = output_stops[stop_id]
        if inp['stop_name'] != out['stop_name']:
            print(f'Stop name mismatch for {stop_id}')
        if inp['stop_lat'] != out['stop_lat']:
            print(f'Stop lat mismatch for {stop_id}')
        if inp['stop_lon'] != out['stop_lon']:
            print(f'Stop lon mismatch for {stop_id}')

print('Verification complete')
""}

